package com.smarthub.plus;
import android.app.*;
import android.content.Intent;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.*;
import org.json.*;
import java.net.URLEncoder;
import java.time.*;
import java.text.DateFormat;
import java.util.*;
import java.util.concurrent.*;
public final class PrayerActivity extends HubActivity {
 private CheckBox remindersSwitch;private final ExecutorService worker=Executors.newSingleThreadExecutor();private LinearLayout details;private TextView status;private EditText city,country;private Spinner method;private int generation;private boolean dead;private final int[] methods={3,0,4,5,8,16};
 @Override public void onCreate(Bundle s){super.onCreate(s);LinearLayout body=page(tx("الصلاة ورمضان","Prayer & Ramadan"),tx("AlAdhan • حسب المدينة وطريقة الحساب المختارة","AlAdhan • city and calculation method"));LinearLayout settings=card(body);city=field(settings,tx("المدينة بالإنجليزية","City in English"),prefs().getString("prayer_city","Baghdad"));country=field(settings,tx("الدولة بالإنجليزية","Country in English"),prefs().getString("prayer_country","Iraq"));method=new Spinner(this);String[] choices=ar?new String[]{"رابطة العالم الإسلامي","الجعفري / الإثنا عشري","أم القرى","الهيئة المصرية","الخليج","دبي"}:new String[]{"Muslim World League","Jafari / Ithna Ashari","Umm Al-Qura","Egyptian Authority","Gulf Region","Dubai"};ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,choices);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);method.setAdapter(a);int saved=prefs().getInt("prayer_method",3);for(int j=0;j<methods.length;j++)if(methods[j]==saved)method.setSelection(j);settings.addView(method);
  action(settings,tx("تحديث جدول الشهر","Fetch this month's timetable"),()->fetch(false));action(settings,tx("جدول رمضان القادم","Next Ramadan timetable"),()->fetch(true));CheckBox alerts=check(settings,tx("تنبيه قبل الصلاة بخمس دقائق","Five minute prayer reminders"),prefs().getBoolean("prayer_alerts",false));remindersSwitch=alerts;alerts.setOnCheckedChangeListener((v,on)->{if(on&&Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){prefs().edit().putBoolean("prayer_alerts",false).apply();alerts.setChecked(false);requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},55);return;}prefs().edit().putBoolean("prayer_alerts",on).apply();PrayerScheduler.schedule(this);});action(settings,tx("إعداد دقة التنبيهات","Reminder precision settings"),()->{if(Build.VERSION.SDK_INT>=31){try{startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}catch(Exception ignored){toast(tx("غير متاح على هذا النظام","Not available on this system"));}}});note(settings,tx("التنبيهات تتبع وقت المدينة المختارة. قد يؤخرها توفير الطاقة دون إذن التنبيهات الدقيقة. رمضان حسب تقويم المصدر؛ راجع الإعلان المحلي لبداية الشهر.","Reminders follow the selected city's timezone. Battery saving may delay reminders without exact-alarm access. Ramadan dates follow the provider calendar; check the local month announcement."));action(settings,tx("إعدادات إشعارات التطبيق","App notification settings"),()->{try{startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}catch(Exception e){toast(e.getMessage());}});status=text("",14,false);body.addView(status);details=col();body.addView(details);render(HubFiles.read(this,"prayers.json"),false);}
 private void fetch(boolean ramadan){String c=city.getText().toString().trim(),co=country.getText().toString().trim();if(c.isEmpty()||co.isEmpty()){toast(tx("أدخل المدينة والدولة","Enter city and country"));return;}int m=methods[method.getSelectedItemPosition()],request=++generation;status.setText(tx("جارٍ جلب الجدول…","Fetching timetable…"));prefs().edit().putString("prayer_city",c).putString("prayer_country",co).putInt("prayer_method",m).apply();worker.execute(()->{try{LocalDate now=LocalDate.now();String path="calendarByCity/"+now.getYear()+"/"+now.getMonthValue();if(ramadan){JSONObject cache=HubFiles.read(this,"prayers.json");JSONObject today=cache==null?null:PrayerData.find(cache.optJSONArray("data"),now);if(today==null)throw new IllegalStateException("حدّث جدول الشهر أولاً / Fetch current month first");JSONObject hijri=today.getJSONObject("date").getJSONObject("hijri");int year=hijri.getInt("year");if(hijri.getJSONObject("month").getInt("number")>9)year++;path="hijriCalendarByCity/"+year+"/9";}String url="https://api.aladhan.com/v1/"+path+"?city="+URLEncoder.encode(c,"UTF-8")+"&country="+URLEncoder.encode(co,"UTF-8")+"&method="+m;JSONObject data=new JSONObject(HubHttp.get(url));if(data.optInt("code")!=200||data.optJSONArray("data")==null)throw new IllegalStateException("Invalid calendar response");data.put("city",c).put("country",co).put("method",m).put("fetchedAt",System.currentTimeMillis());HubFiles.save(this,ramadan?"ramadan.json":"prayers.json",data);if(!ramadan)PrayerScheduler.schedule(this);runOnUiThread(()->{if(!dead&&request==generation)render(data,ramadan);});}catch(Exception e){runOnUiThread(()->{if(!dead&&request==generation){status.setText(tx("تعذر التحديث؛ تبقى النسخة المحفوظة: ","Update failed; cached timetable retained: ")+e.getMessage());}});}});}
 private void render(JSONObject saved,boolean ramadan){details.removeAllViews();if(saved==null){status.setText(tx("لم يتم تحميل جدول بعد","No timetable downloaded yet"));return;}try{JSONArray days=saved.getJSONArray("data");JSONObject first=days.getJSONObject(0);ZoneId zone=PrayerData.zone(first);LocalDate local=LocalDate.now(zone);JSONObject today=PrayerData.find(days,local);status.setText(tx("نسخة محفوظة • ","Saved timetable • ")+saved.optString("city")+" • "+DateFormat.getDateTimeInstance().format(new Date(saved.optLong("fetchedAt")))+" • "+zone);
  if(!ramadan){if(today==null)note(details,tx("الجدول المحفوظ لشهر مختلف؛ حدّث بيانات الشهر الحالي.","The saved timetable is from another month. Fetch the current month."));else{JSONObject h=today.getJSONObject("date").getJSONObject("hijri");LinearLayout d=card(details);d.addView(text(local+" • "+h.optString("date")+" هـ",21,true));JSONObject times=today.getJSONObject("timings");String[] labels=ar?new String[]{"الفجر","الشروق","الظهر","العصر","المغرب","العشاء"}:new String[]{"Fajr","Sunrise","Dhuhr","Asr","Maghrib","Isha"};String[] keys={"Fajr","Sunrise","Dhuhr","Asr","Maghrib","Isha"};for(int j=0;j<keys.length;j++){TextView line=text(labels[j]+"     "+times.optString(keys[j]),20,false);line.setPadding(0,dp(6),0,dp(6));d.addView(line);}}}
  LinearLayout month=card(details);month.addView(text(ramadan?tx("رمضان • الإمساك والإفطار","Ramadan • Imsak and Iftar"):tx("تقويم الشهر","Month calendar"),20,true));for(int j=0;j<days.length();j++){JSONObject day=days.getJSONObject(j),g=day.getJSONObject("date").getJSONObject("gregorian"),t=day.getJSONObject("timings");String line=g.optString("date")+"     "+(ramadan?"Imsak "+t.optString("Imsak")+"   Maghrib "+t.optString("Maghrib"):"Fajr "+t.optString("Fajr")+"   Maghrib "+t.optString("Maghrib"));TextView entry=text(line,15,false);entry.setPadding(0,dp(8),0,dp(8));month.addView(entry);}
 }catch(Exception e){status.setText(tx("الجدول المحفوظ غير صالح","Stored timetable is invalid"));}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==55){boolean allowed=grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED;prefs().edit().putBoolean("prayer_alerts",allowed).apply();if(remindersSwitch!=null)remindersSwitch.setChecked(allowed);PrayerScheduler.schedule(this);if(!allowed)toast(tx("التنبيهات متوقفة حتى تسمح بالإشعارات من الإعدادات","Reminders are off until notifications are allowed in settings"));}}
 @Override protected void onResume(){super.onResume();String error=prefs().getString("prayer_refresh_error","");if(!error.isEmpty()&&status!=null)status.setText(error);}
 @Override protected void onDestroy(){dead=true;generation++;worker.shutdownNow();super.onDestroy();}
}
